/* Backstage: Produktkatalog (produkter, grupper, varianter, ingredienser, tillval, prislistor, import, popup-meddelanden). */
(()=>{const {D,B,F,go,INIT,btoast,sub,lbl,inp,ta,dd,OPTHOOK,isOn,tgl,chk,rad,rcard,head,addPill,actPill,foot,BACK,need,SW,swOf,dmy,kr,ibtn,tool,pager,tabs,dlg,openDlg,sideP,PG,SAVES,FOOT,pickDlg,pickedTable,addBox,today}=BS;
sub('groupform','Lägg till ny produktgrupp','products');sub('prodform','Lägg till ny produkt','products');sub('product','Produkt','products');sub('optform','Skapa alternativ','options');sub('ingform','Lägg till ny ingrediens','ingredients');sub('inggroup','Lägg till ingrediensgrupp','ingredients');
sub('modform','Skapa ny tillvalsgrupp','modifiers');sub('modset','Tillvalsgrupp','modifiers');sub('plprods','Hantera produktpriser','pricelists');sub('popform','Lägg till popup-meddelande','popup');
Object.assign(BACK,{groupform:'products',prodform:'products',product:'products',optform:'options',ingform:'ingredients',inggroup:'ingredients',modform:'modifiers',modset:'modifiers',plprods:'pricelists',popform:'popup'});
const tr=`<hr class="d"><button class="pill" style="opacity:.5"><span class="ms" style="background:#999">add</span>Lägg till översättning</button><hr>`;
const img=t=>`${lbl(t)}<div class="imgbox"><div><span class="ms">add_photo_alternate</span><br>Dra bilden hit eller klicka för att välja en fil</div></div>`;

/* ── Produkter ── */
PG.products=()=>{const b=B();const fg=b.fg;const L=fg?S.products.filter(p=>p.gid===fg):S.products.slice().sort((a,c)=>a.name.localeCompare(c.name,'sv'));
 return head(['Produkter'],'Produktkatalog',`<span class="lbl" style="font-weight:600">Välj visningsspråk för katalogen</span><div style="width:216px">${dd('b_lang',['Svenska','English'],'Svenska')}</div>`)+`<div class="bsbody"><div style="display:flex;align-items:center;gap:10px"><h2 style="font-size:20px;margin:0;padding-right:12px;border-right:1px solid #ddd;font-weight:500">Produktgrupper</h2><button data-a="bsgo" data-x="groupform" data-g="bs-grp-add" style="display:grid"><span class="ms" style="font-size:22px">add_circle</span></button><span class="ms" style="font-size:20px">info</span></div>
  <div class="chips">${S.groups.map(g=>`<button class="chip ${(g.color||'').toLowerCase()==='#ffffff'?'n':''} ${fg===g.id?'sel':''}" style="background:${g.color}" data-a="bsfg" data-x="${g.id}" data-g="chip-${slug(g.name)}" data-sort="g" data-id="${g.id}"><span class="dh" data-drag="g" data-g="gdrag-${slug(g.name)}" title="Dra för att ändra ordning">⠿</span>${esc(g.name)}</button>`).join('')}</div>
  <button style="margin-top:14px;border:1px solid #bbb;border-radius:3px;padding:6px 9px;font-size:10.5px;font-weight:700" data-a="bsfg" data-x="">${fg?'VISA ALLA PRODUKTER':'VISA PRODUKTER UTAN GRUPP'}</button>
  ${fg?`<div style="display:flex;gap:14px;margin-top:12px;font-size:12px">${ibtn('edit','bsgo','groupform|'+fg,'grp-edit','Redigera gruppen')}${ibtn('delete','bsgrpdel',fg,'grp-del','Ta bort')}</div>`:''}<hr>
  <div class="rowr">${addPill('Lägg till produkter','prodform','bs-prod-add')}</div>
  <div class="tool"><input class="bi sb" placeholder="Sök på produktnamn, SKU eller EAN" style="height:28px;font-style:italic"><span style="font-size:11px;margin-left:8px">${(b.psel||[]).length}/${S.products.length} valda produkter</span><div class="tb2"><button class="pill" style="padding:5px 10px;${(b.psel||[]).length?'':'opacity:.5'}" data-a="${(b.psel||[]).length?'bsgo':'nop'}" data-x="bulk" data-g="bulk-edit"><span class="ms" style="background:none;color:#111">edit</span>Redigera alla markerade</button><button class="pill" style="padding:5px 10px;opacity:.5"><span class="ms" style="background:none;color:#111">delete</span>Radera markerade</button><span><span class="ms">sort</span>Sortera</span><span><span class="ms">tune</span>Filter</span><span><span class="ms">view_column</span>Kolumner <small style="color:#888">5/5</small></span></div></div>
  <table class="bt"><tr>${fg?'<th style="width:22px"></th>':''}<th style="width:24px"><span class="chk"></span></th><th>${fg?'Produktnamn':'Produktnamn ▲'}</th><th>Typ av produkt</th><th>Synlig</th><th>Standardpris</th><th>Avhämtning (moms 6%)</th><th>Enhet</th><th>Grupp | Undergrupp</th><th style="width:64px"></th></tr>
  ${L.map(p=>{const g=G(p.gid);const sel=(b.psel||[]).includes(p.id);const tp=(D().priceLists[0]||{prices:{}}).prices[p.id];const sp=slug(p.name);
  const hd=fg?`<td><span class="dh" data-drag="p" data-g="pdrag-${sp}" title="Dra för att ändra ordning">⠿</span></td>`:'';
  if(b.inl===p.id)return `<tr data-g="prow-${sp}" style="background:#f4f4f4">${hd}<td></td><td>${inp('b_il_name',{st:'height:28px'})}</td><td><span class="bbdg">${p.variants?'VARIANTER':'VANLIG'}</span></td><td><span class="ms" style="font-size:17px">${p.hidden?'visibility_off':'visibility'}</span></td><td>${p.open?'Öppet pris':inp('b_il_price',{type:'number',st:'height:28px'})}</td><td>${b.inlTake||tp!=null?inp('b_il_take',{type:'number',st:'height:28px'}):`<button data-a="bsiltake" data-g="il-take" style="display:inline-flex;align-items:center;gap:4px;font-weight:600"><span class="ms" style="font-size:16px">add_circle</span>Lägg till pris</button>`}</td><td>${esc(UABBR[p.unit||'Styck (st)']||'st')}</td><td>${dd('b_il_gid',S.groups.map(x=>[x.id,x.name.toUpperCase()]),'Välj grupp')}</td><td style="white-space:nowrap">${ibtn('close','bsilx','','il-cancel')} ${ibtn('more_vert','bspmenu',p.id,'pmenu-'+sp)}</td></tr>`;
  return `<tr data-g="prow-${sp}" data-sort="p" data-id="${p.id}">${hd}<td><button data-a="bspsel" data-x="${p.id}" data-g="psel-${sp}"><span class="chk ${sel?'on':''}"></span></button></td><td><button data-a="bsgo" data-x="product|${p.id}" data-g="pname-${sp}" style="text-align:left;cursor:pointer">${esc(p.name)}</button></td><td><span class="bbdg">${p.variants?'VARIANTER':'VANLIG'}</span></td><td><span class="ms" style="font-size:17px">${p.hidden?'visibility_off':'visibility'}</span></td><td>${p.open?'Öppet pris':kr(p.price)} <span style="color:#888">(${g?g.vat:12} %)</span></td><td>${tp!=null?kr(tp):'-'}</td><td>${esc(UABBR[p.unit||'Styck (st)']||'st')}</td><td>${esc((g?g.name:'').toUpperCase())}</td><td style="white-space:nowrap;position:relative">${ibtn('edit','bsinl',p.id,'pedit-'+sp)} ${ibtn('more_vert','bspmenu',p.id,'pmenu-'+sp)}${b.pmenu===p.id?`<div class="pmenu" style="position:absolute;right:0;top:30px;z-index:30;background:#fff;border-radius:10px;box-shadow:0 4px 18px rgba(0,0,0,.18);padding:6px 4px;min-width:190px;text-align:left">${[['open_in_new','bsgo','product|'+p.id,'pm-open','Gå till produkt'],['content_copy','bspcopy',p.id,'pm-copy','Kopiera produkt'],['delete','bspdel',p.id,'pm-del','Radera produkt']].map(([ic,a,x,gg,t],i)=>`<button data-a="${a}" data-x="${x}" data-g="${gg}" style="display:flex;align-items:center;gap:10px;width:100%;padding:9px 12px;font-weight:700;font-size:12px;${i?'border-top:1px solid #eee':''}"><span class="ms" style="font-size:18px">${ic}</span>${t}</button>`).join('')}</div>`:''}</td></tr>`}).join('')}</table>${pager(L.length)}</div>`};
A.bsfg=x=>{B().fg=x||null;render();emit('bs:fg',x)};
A.bspsel=id=>{const b=B();b.psel=b.psel||[];const i=b.psel.indexOf(id);i<0?b.psel.push(id):b.psel.splice(i,1);render();emit('bs:psel')};
A.bspdel=id=>{const p=P(id);BS.bconfirm({t:'Ta bort produkt',p:`Vill du ta bort ${p.name}?`,ok:'Ta bort',red:1},ok=>{if(!ok)return;S.products=S.products.filter(x=>x.id!==id);save();btoast('Produkten har tagits bort');emit('bs:pdel')})};
A.bsinl=id=>{const b=B();const p=P(id);b.inl=id;b.pmenu=null;b.inlTake=false;const tp=(D().priceLists[0]||{prices:{}}).prices[id];Object.assign(UI.f,{b_il_name:p.name,b_il_price:String(p.price||0),b_il_take:tp!=null?String(tp):'',b_il_gid:p.gid});render();emit('bs:inline')};
A.bsilx=()=>{const b=B();b.inl=null;b.inlTake=false;render();emit('bs:inline:x')};
A.bsiltake=()=>{const p=P(B().inl);B().inlTake=true;UI.f.b_il_take=String(p.price||0);render();emit('bs:inline:take')};
A.bsilsave=()=>{const b=B();const p=P(b.inl);if(!p)return;if(!need(['b_il_name']))return;p.name=F('b_il_name').trim();if(!p.open&&F('b_il_price')!=='')p.price=+F('b_il_price');if(F('b_il_gid'))p.gid=F('b_il_gid');const pl=D().priceLists[0];if(pl&&F('b_il_take')!=='')pl.prices[p.id]=+F('b_il_take');b.inl=null;b.inlTake=false;save();render();btoast('Produkten har sparats');emit('bs:save:inline',p)};
A.bspmenu=id=>{const b=B();b.pmenu=b.pmenu===id?null:id;render();emit('bs:pmenu')};
A.bspcopy=id=>{const p=P(id);const c=JSON.parse(JSON.stringify(p));c.id='p'+Date.now().toString(36);c.name=p.name+' (kopia)';delete c.stock;S.products.push(c);S.modifiers.forEach(m=>{if(m.pids.includes(id)&&!m.variant)m.pids.push(c.id)});B().pmenu=null;save();render();btoast('Produkten har kopierats')};
FOOT.products=()=>B().inl?`<div class="bsfoot"><button class="bcan" data-a="bsilx" data-g="il-cancel2">Avbryt</button><button class="bsave" data-a="bsilsave" data-g="bs-save"><span><span class="ms">save</span>Spara</span></button></div>`:'';
{const oi=INIT.products;INIT.products=a=>{const b=B();b.inl=null;b.pmenu=null;if(oi)oi(a)}}
A.bsgrpdel=id=>{const g=G(id);BS.bconfirm({t:'Ta bort produktgrupp',p:`Om du raderar ${g.name} raderas även alla produkter i gruppen.`,ok:'Ta bort',red:1},ok=>{if(!ok)return;S.groups=S.groups.filter(x=>x.id!==id);S.products=S.products.filter(p=>p.gid!==id);B().fg=null;save();btoast('Produktgruppen har tagits bort')})};
sub('bulk','Redigera alla markerade','products');BACK.bulk='products';
PG.bulk=()=>head(['Produkter','Redigera alla markerade'],'Redigera alla markerade')+`<div class="bsbody"><p class="lead">${(B().psel||[]).length} produkter är markerade. Fält som lämnas tomma ändras inte.</p><div class="grid2" style="margin-top:14px"><div>${lbl('Nytt pris inkl. moms')}${inp('b_bprice',{type:'number',ph:'SEK'})}</div><div>${lbl('Ny produktgrupp')}${dd('b_bgid',S.groups.map(g=>[g.id,g.name]),'Behåll nuvarande')}</div></div></div>`;
SAVES.bulk=['bssavebulk'];
A.bssavebulk=()=>{const L=B().psel||[];L.forEach(id=>{const p=P(id);if(!p)return;if(F('b_bprice'))p.price=+F('b_bprice');if(F('b_bgid'))p.gid=F('b_bgid')});save();B().psel=[];go('products');btoast(L.length+' produkter har uppdaterats');emit('bs:save:bulk')};

/* product group form (new + edit) */
INIT.groupform=id=>{const g=id&&G(id);if(g)Object.assign(UI.f,{b_gname:g.name,b_gvat:String(g.vat),b_gledger:g.ledger||'',b_gcolor:(SW.find(s=>s[1].toLowerCase()===String(g.color).toLowerCase())||['Neutral'])[0],b_gpop:!!g.popup,b_gpopid:g.popup||''})};
PG.groupform=()=>{const ed=B().arg;return head(['Produkter',ed?'Redigera produktgrupp':'Lägg till ny produktgrupp'],ed?'Redigera produktgrupp':'Lägg till ny produktgrupp')+`<div class="bsbody"><h3 style="margin-top:0">Produktgruppsinformation</h3>
 <div style="display:grid;grid-template-columns:568px 284px;gap:12px"><div>${lbl('Namn',1)}<div style="width:284px">${inp('b_gname')}</div><div style="margin-top:12px">${lbl('Beskrivning')}${ta('b_gdesc')}</div></div><div>${img('Bild som visas i Yabie Online')}</div></div>${tr}
 <h3>Bokföring</h3><div class="grid2"><div>${lbl('Momssats',1)}${ed?`<input class="bi" value="${esc(F('b_gvat'))} %" readonly style="background:#f3f3f3">`:dd('b_gvat',[['25','25 %'],['12','12 %'],['6','6 %'],['0','0 %']],'Välj momssats',{label:v=>v+' %'})}<div class="help">Du kan inte ändra momssats för en befintlig produktgrupp. Behöver du ändra momssatsen för produkterna i den här gruppen? Skapa en ny grupp med korrekt momssats. Flytta sedan dina produkter till den nya gruppen.</div></div><div>${lbl('Bokföringskonto',1)}${inp('b_gledger')}</div></div><hr>
 <div class="grid2"><div>${lbl('Färg',1)}${dd('b_gcolor',SW.map(s=>[s[0],s[0],s[1]]),'Välj färg')}</div><div>${lbl('Externt Id')}${inp('b_gext')}</div></div><hr>
 <h3>Produkttillgänglighet</h3>${lbl('Koppla gruppen till de butiker där den ska synas',1)}${rad('b_gav','all','Alla butiker','all')}${rad('b_gav','sel','Välj butiker','all')}<hr>
 <h3>Popup-meddelande</h3><p class="lead" style="margin-bottom:10px">Det här meddelandet kommer att visas för alla produkter i gruppen</p><div class="tgrow">Lägg till popup-meddelande${tgl('b_gpop')}</div>${isOn('b_gpop')?`<div style="width:284px;margin-top:10px">${lbl('Popup-meddelande',1)}${dd('b_gpopid',D().popups.map(p=>[p.id,p.name]),'Välj meddelande')}</div>`:''}</div>`};
OPTHOOK.b_gvat=v=>{if(!F('b_gledger'))UI.f.b_gledger={25:'3001',12:'3002',6:'3003',0:'3004'}[v]};
SAVES.groupform=['bssavegroup'];
A.bssavegroup=()=>{if(!need(['b_gname','b_gvat','b_gledger','b_gcolor']))return;const ed=B().arg;const data={name:F('b_gname').trim(),vat:+F('b_gvat'),ledger:F('b_gledger'),color:swOf(F('b_gcolor')),popup:isOn('b_gpop')?F('b_gpopid')||null:null};
 let g;if(ed){g=G(ed);Object.assign(g,data)}else{g={id:'g'+Date.now().toString(36),...data};S.groups.push(g)}save();go('products');B().fg=ed||null;render();btoast(ed?'Produktgruppen har sparats':'Produktgruppen har skapats');emit('bs:save:group',g)};

/* product form: new product and the product view with tabs */
const UNITS=['Styck (st)','Timmar (h)','Gram (g)','Kilogram (kg)','Meter (m)','Kilometer (km)','Milliliter (ml)','Centiliter (cl)','Liter (l)'];const UABBR=Object.fromEntries(UNITS.map(u=>[u,u.match(/\((.+)\)/)[1]]));
const ALLERG=['Gluten','Skaldjur','Ägg','Fisk','Jordnötter','Sojabönor','Mjölk','Trädnötter','Selleri','Senap','Sesam','Svaveldioxid','Lupin','Musslor','Bipollen'];
const DIETS=['Vegetarian','Vegan','Halal','Kosher','Mjölkfri','Glutenfri','Nötfri','Sojafri','Laktosfri'];
function prodInfo(isNew){const gs=S.groups.map(g=>[g.id,g.name]);const varT=(F('b_ptype')||'reg')==='var';const al=UI.f.b_pallerg||[];
 return `<h2 style="font-size:16px">Produktinformation</h2>${isNew?`<h3>Typ av produkt</h3><div class="grid2" style="grid-template-columns:304px 304px">${rcard('b_ptype','reg','Vanlig produkt','Säljs som en enda typ av produkt','reg')}${rcard('b_ptype','var','Produkt med varianter','Säljs i olika varianter så som färg, storlek och mönster','reg')}</div><hr class="d">`:''}
 ${isNew&&varT?`<div style="background:#f6f6f6;border-radius:4px;padding:12px;max-width:620px;margin-bottom:12px"><b style="font-size:12px">Alternativ för varianter</b><div class="note" style="margin:2px 0 8px">Välj ett helt alternativ eller bara vissa värden. Alternativet måste finnas innan produkten skapas.</div>${D().options.map(o=>`<div style="margin:6px 0"><b style="font-size:11.5px">${esc(o.name)}</b><div class="crow" style="flex-wrap:wrap">${o.values.map(v=>{const k='b_pv_'+o.id+'_'+slug(v);return chk(k,esc(v))}).join('')}</div></div>`).join('')||'<i>Inga alternativ skapade ännu.</i>'}</div>`:''}
 <div style="display:grid;grid-template-columns:304px 304px 304px;gap:12px;align-items:end"><div>${lbl('Produktgrupp',1)}${dd('b_pgid',gs,'Sök produktgrupp',{label:v=>(G(v)||{}).name||v})}</div><div style="display:flex;align-items:center;gap:8px;font-size:12px;height:31px">${tgl('b_pvis',1)}Produkten är synlig <span class="ms" style="font-size:15px">info</span></div><div style="display:flex;align-items:center;gap:8px;font-size:12px;height:31px">${tgl('b_psold',1)}Produkten går att sälja <span class="ms" style="font-size:15px">info</span></div></div><hr class="d">
 <div style="display:grid;grid-template-columns:620px 304px;gap:12px"><div>${lbl('Namn',1)}<div style="width:304px">${inp('b_pname')}</div><div style="margin-top:12px">${lbl('Beskrivning')}${ta('b_pdesc')}</div></div><div>${img('Bild som visas i kassan')}</div></div>${tr}
 <h3>Enhet</h3>${lbl('Enhet',1)}<div style="width:304px">${dd('b_punit',UNITS,'Styck (st)')}</div><hr>
 <h3>Pris</h3>${lbl('Pristyp',1)}${rad('b_pptype','fixed','Fast pris','fixed')}${rad('b_pptype','var','Öppet pris','fixed')}
 ${(F('b_pptype')||'fixed')==='fixed'?`<div style="background:#e3fbef;border:1px solid #9be3bf;border-radius:3px;padding:12px;margin-top:10px;width:620px;box-sizing:border-box"><b style="font-size:11.5px">Standardpris</b><div class="grid2" style="margin-top:8px;grid-template-columns:1fr 1fr"><div>${lbl('Pris inkl. moms',1)}${inp('b_pprice',{ph:'SEK',type:'number'})}</div><div>${lbl('Inköpspris exkl. moms')}${inp('b_pcost',{ph:'SEK',type:'number'})}</div></div></div>`:`<p class="lead" style="margin-top:8px">Priset anges i kassan varje gång produkten säljs.</p>`}
 <h3>Ytterligare priser</h3><p class="lead" style="margin-bottom:8px">Aktivera prislista och ange pris som ska användas</p>${D().priceLists.map(l=>`<div class="tgrow" style="max-width:596px;margin-bottom:6px"><b style="font-weight:600"><span class="ms" style="font-size:15px;vertical-align:-3px">info</span> ${esc(l.name)}</b>${tgl('b_ppl_'+l.id)}</div>${isOn('b_ppl_'+l.id)?`<div style="width:300px;margin:4px 0 10px">${lbl('Pris i prislistan')}${inp('b_pplp_'+l.id,{type:'number',ph:'SEK'})}</div>`:''}`).join('')}<hr>
 <h3>Allergener och specialkost</h3><p class="lead">Lägg till information om allergener och specialkost för att hålla personal och kunder informerade.</p>${al.length?`<div class="chips" style="margin:8px 0">${al.map(a=>`<span class="chip n">${esc(a)}</span>`).join('')}</div>`:''}<button class="addbox" style="max-width:620px;margin:8px 0" data-a="bsallerg" data-g="bs-allerg"><span class="ms">add</span>Lägg till allergener och specialkost</button><div style="display:flex;align-items:center;gap:8px;font-size:12px">${tgl('b_pallow',1)}Tillåt allergiönskemål för denna produkt</div><hr>
 <h3>Produkttillgänglighet</h3>${lbl('Koppla produkten till butikerna där den ska synas',1)}${rad('b_pav','all','Alla butiker','all')}${rad('b_pav','sel','Välj butiker','all')}<hr>
 <div style="width:304px">${lbl('Varumärke')}${inp('b_pbrand')}</div><hr><div class="grid2" style="grid-template-columns:304px 304px"><div>${lbl('SKU / PLU')}${inp('b_pplu')}</div><div>${lbl('EAN/Streckkodsnummer')}${inp('b_pean')}</div></div><hr>
 <h3>Popup-meddelande</h3><p class="lead" style="margin-bottom:10px">Popup-meddelandet visas när produkten läggs till i varukorgen</p><div class="tgrow" style="max-width:596px">Lägg till popup-meddelande${tgl('b_ppop')}</div>${isOn('b_ppop')?`<div style="width:300px;margin-top:10px">${dd('b_ppopid',D().popups.map(p=>[p.id,p.name]),'Välj meddelande')}</div>`:''}
 ${B().dlg==='allerg'?dlg('Allergener och specialkost',`<h3 style="margin-top:0">Allergener</h3><div class="crow" style="flex-wrap:wrap;gap:4px 14px">${ALLERG.map(a=>chk('b_al_'+slug(a),a)).join('')}</div><h3>Specialkost</h3><div class="crow" style="flex-wrap:wrap;gap:4px 14px">${DIETS.map(a=>chk('b_al_'+slug(a),a)).join('')}</div><hr>${chk('b_al_none','Inga allergener')}`,`<button data-a="bsdlgx">Avbryt</button><button class="p" data-a="bsallergok" data-g="allerg-ok">Spara</button>`,{wide:1}):''}`}
A.bsallerg=()=>{(UI.f.b_pallerg||[]).forEach(a=>UI.f['b_al_'+slug(a)]=true);openDlg('allerg','bs:dlg:allerg')};
A.bsallergok=()=>{UI.f.b_pallerg=[...ALLERG,...DIETS,'Inga allergener'].filter(a=>UI.f['b_al_'+slug(a==='Inga allergener'?'none':a)]||(a==='Inga allergener'&&UI.f.b_al_none));B().dlg=null;render();emit('bs:allerg')};
PG.prodform=()=>head(['Produkter','Lägg till ny produkt'],'Lägg till ny produkt')+`<div class="bsbody">${prodInfo(true)}</div>`;
SAVES.prodform=['bssaveprod'];
function readProd(p){const fixed=(F('b_pptype')||'fixed')==='fixed';Object.assign(p,{name:F('b_pname').trim(),price:fixed?+F('b_pprice')||0:0,open:!fixed,gid:F('b_pgid'),desc:F('b_pdesc'),unit:F('b_punit')||'Styck (st)',hidden:!isOn('b_pvis',1),plu:F('b_pplu')||undefined,ean:F('b_pean')||undefined,allergy:UI.f.b_pallerg||[],popup:isOn('b_ppop')?F('b_ppopid')||null:null});
 D().priceLists.forEach(l=>{if(isOn('b_ppl_'+l.id)&&F('b_pplp_'+l.id))l.prices[p.id]=+F('b_pplp_'+l.id);else if(UI.f['b_ppl_'+l.id]===false)delete l.prices[p.id]})}
A.bssaveprod=()=>{const keys=['b_pgid','b_pname'];if((F('b_pptype')||'fixed')==='fixed')keys.push('b_pprice');if(!need(keys))return;
 const varT=(F('b_ptype')||'reg')==='var';const vals=[];if(varT)D().options.forEach(o=>o.values.forEach(v=>{if(UI.f['b_pv_'+o.id+'_'+slug(v)])vals.push({opt:o.name,v})}));if(varT&&!vals.length){btoast('Välj minst ett variantvärde');return}
 const p={id:'p'+Date.now().toString(36)};readProd(p);if(varT){p.variants=vals.map(x=>({name:x.v,opt:x.opt,price:p.price}));const m={id:'mv'+p.id,name:vals[0].opt,multi:false,req:true,opts:vals.map(x=>({name:x.v,price:0})),pids:[p.id],variant:1};S.modifiers.push(m)}
 S.products.push(p);save();go('product',p.id);btoast('Produkten har skapats');emit('bs:save:product',p)};
INIT.product=id=>{const p=P(id);if(!p)return;Object.assign(UI.f,{b_pname:p.name,b_pgid:p.gid,b_pdesc:p.desc||'',b_pprice:String(p.price||''),b_pptype:p.open?'var':'fixed',b_punit:p.unit||'Styck (st)',b_pvis:!p.hidden,b_pplu:p.plu||'',b_pean:p.ean||'',b_pallerg:[...(p.allergy||[])],b_ppop:!!p.popup,b_ppopid:p.popup||''});D().priceLists.forEach(l=>{if(l.prices[p.id]!=null){UI.f['b_ppl_'+l.id]=true;UI.f['b_pplp_'+l.id]=String(l.prices[p.id])}})};
const PTABS=p=>[['info','Produktinformation'],...(p.variants?[['var','Varianter']]:[]),['stock','Lager'],['mods','Tillval'],['rec','Rekommendationer'],['ing','Ingredienser']];
PG.product=()=>{const p=P(B().arg);if(!p)return head(['Produkter'],'Produkten finns inte');const t=B().tab||'info';
 let body='';
 if(t==='info')body=prodInfo(false);
 if(t==='var')body=`<h2 style="font-size:16px">Varianter</h2><p class="lead">Ange pris per variant vid behov.</p><table class="bt" style="max-width:620px;margin-top:12px"><tr><th>Variant</th><th>Pris inkl. moms</th></tr>${p.variants.map((v,i)=>`<tr><td>${esc(v.opt)}: ${esc(v.name)}</td><td>${inp('b_vp_'+i,{type:'number',ph:String(v.price),st:'height:26px'})}</td></tr>`).join('')}</table>`;
 if(t==='stock'){const st=p.stock;body=`<h2 style="font-size:16px">Lager</h2>${!st?`<p class="lead">Lagerhantering är inte aktiverad för produkten.</p><button class="pill" style="margin-top:12px" data-a="bsstockon" data-g="stock-on"><span class="ms">inventory</span>Aktivera lagerhantering</button>`:`<div class="kpis" style="grid-template-columns:repeat(3,1fr);max-width:720px"><div class="kpi"><small>Lagersaldo</small><b>${st.qty} st</b></div><div class="kpi"><small>Lågt lagersaldo</small><b>${st.low?st.limit+' st':'Av'}</b></div><div class="kpi"><small>Lagerplats</small><b style="font-size:16px">Kaffebaren</b></div></div>
  <button class="pill" data-a="bsstockedit" data-g="stock-edit"><span class="ms">edit</span>Redigera</button><hr><div class="tgrow" style="max-width:596px">Lågt lagersaldo${tgl('b_slow',st.low)}</div>${isOn('b_slow',st.low)?`<div style="width:300px;margin-top:10px">${lbl('Gräns för lågt lagersaldo',1)}${inp('b_slimit',{type:'number',ph:String(st.limit||5)})}</div>`:''}
  <h3>Historik</h3><table class="bt" style="max-width:720px"><tr><th>Datum</th><th>Ändring</th><th>Personal</th><th>Anledning</th></tr>${(st.log||[]).map(l=>`<tr><td>${esc(l.at)}</td><td>${l.d>0?'+':''}${l.d}</td><td>${esc(l.who)}</td><td>${esc(l.why)}</td></tr>`).join('')||'<tr><td colspan="4"><i>Inga ändringar ännu</i></td></tr>'}</table>`}
  ${B().dlg==='stock'?dlg('Uppdatera lagersaldo',`${lbl('Lagersaldo',1)}${inp('b_sqty',{type:'number'})}<div style="margin-top:10px">${lbl('Personal',1)}${dd('b_swho',D().users.map(u=>u.first+' '+u.last),'Välj personal')}</div><div style="margin-top:10px">${lbl('Anledning',1)}${dd('b_swhy',['Leverans','Inventering','Svinn','Skadad vara','Övrigt'],'Välj anledning')}</div>`,`<button data-a="bsdlgx">Avbryt</button><button class="p" data-a="bsstocksave" data-g="stock-save">Spara</button>`,{h:380}):''}`}
 if(t==='mods'){const ms=S.modifiers.filter(m=>m.pids.includes(p.id));body=`<h2 style="font-size:16px">Tillval</h2><p class="lead">Välj vilka tillvalsgrupper som hör till produkten.</p><div class="plist" style="max-width:620px;margin-top:12px">${S.modifiers.filter(m=>!m.variant).map(m=>`<div><button class="cl" style="margin:0" data-a="bspmod" data-x="${m.id}" data-g="pmod-${slug(m.name)}"><span class="chk ${m.pids.includes(p.id)?'on':''}"></span>${esc(m.name)}</button><small style="margin-left:auto;color:#666">${m.opts.length} tillval</small></div>`).join('')}</div>`}
 if(t==='rec'){const r=p.recs||[];body=`<h2 style="font-size:16px">Rekommendationer</h2><p class="lead">Produkterna föreslås i kassan när ${esc(p.name)} läggs i varukorgen.</p>${r.length?`<table class="bt" style="max-width:620px;margin:12px 0"><tr><th>Produkt</th><th style="width:40px"></th></tr>${r.map(id=>`<tr><td>${esc((P(id)||{}).name)}</td><td>${ibtn('delete','bsrecdel',id)}</td></tr>`).join('')}</table>`:''}<div style="margin-top:12px">${addBox('Lägg till produkt','bspick','rec','rec-add')}</div>`+pickDlg()}
 if(t==='ing'){const L=p.ings||[];body=`<h2 style="font-size:16px">Ingredienser</h2><p class="lead">Koppla ingredienser och ange hur mycket som går åt per såld produkt.</p>${L.length?`<table class="bt" style="max-width:620px;margin:12px 0"><tr><th>Ingrediens</th><th>Mängd</th></tr>${L.map(x=>{const i=D().ingredients.find(y=>y.id===x.id)||{};return `<tr><td>${esc(i.name)}</td><td>${x.qty} ${esc(i.unit||'')}</td></tr>`}).join('')}</table>`:''}<div style="margin-top:12px">${addBox('Lägg till ingrediens','bsingadd','','ing-add')}</div>
  ${B().dlg==='ing'?dlg('Lägg till ingrediens',`${lbl('Ingrediens',1)}${dd('b_iid',D().ingredients.map(i=>[i.id,i.name+' ('+i.unit+')']),'Välj ingrediens')}<div style="margin-top:10px">${lbl('Mängd',1)}${inp('b_iqty',{type:'number'})}</div>`,`<button data-a="bsdlgx">Avbryt</button><button class="p" data-a="bsingok" data-g="ing-ok">Spara</button>`,{h:300}):''}`}
 return head(['Produkter',p.name],esc(p.name))+`<div class="bsbody" style="padding-top:12px"><div class="pstab">${PTABS(p).map(([v,l])=>`<button class="${t===v?'on':''}" data-a="bstab" data-x="${v}" data-g="ptab-${v}">${l}</button>`).join('')}</div>${body}</div>`};
FOOT.product=()=>foot('bssaveprod2');
A.bssaveprod2=()=>{const p=P(B().arg);const t=B().tab||'info';
 if(t==='info'){const keys=['b_pgid','b_pname'];if((F('b_pptype')||'fixed')==='fixed')keys.push('b_pprice');if(!need(keys))return;readProd(p)}
 if(t==='var')p.variants.forEach((v,i)=>{if(F('b_vp_'+i))v.price=+F('b_vp_'+i)});
 if(t==='stock'&&p.stock){p.stock.low=isOn('b_slow',p.stock.low);if(F('b_slimit'))p.stock.limit=+F('b_slimit');if(p.stock.low&&!p.stock.limit)p.stock.limit=5}
 save();render();btoast('Produkten har sparats');emit('bs:save:product2',t)};
A.bsstockon=()=>{const p=P(B().arg);p.stock={qty:0,low:false,limit:0,log:[]};save();render();emit('bs:stockon')};
A.bsstockedit=()=>{UI.f.b_sqty=String(P(B().arg).stock.qty);openDlg('stock','bs:dlg:stock')};
A.bsstocksave=()=>{if(!need(['b_sqty','b_swho','b_swhy']))return;const p=P(B().arg);const q=+F('b_sqty');p.stock.log.unshift({at:new Date().toLocaleString('sv-SE').slice(0,16),d:q-p.stock.qty,who:F('b_swho'),why:F('b_swhy')});p.stock.qty=q;save();B().dlg=null;render();btoast('Lagersaldot har uppdaterats');emit('bs:stocksave')};
A.bspmod=id=>{const m=S.modifiers.find(x=>x.id===id);const pid=B().arg;const i=m.pids.indexOf(pid);i<0?m.pids.push(pid):m.pids.splice(i,1);save();render();emit('bs:pmod')};
A.bsrecdel=id=>{const p=P(B().arg);p.recs=(p.recs||[]).filter(x=>x!==id);save();render()};
A.bsingadd=()=>openDlg('ing','bs:dlg:ing');
A.bsingok=()=>{if(!need(['b_iid','b_iqty']))return;const p=P(B().arg);(p.ings=p.ings||[]).push({id:F('b_iid'),qty:+F('b_iqty')});save();B().dlg=null;render();btoast('Ingrediensen har kopplats');emit('bs:ingok')};
/* recommendations use the shared picker */
const _pok=A.bspickok;A.bspickok=()=>{const b=B();if(b.pickFor!=='rec')return _pok();const p=P(b.arg);p.recs=[...new Set([...(p.recs||[]),...b.pick.p,...S.products.filter(x=>b.pick.g.includes(x.gid)).map(x=>x.id)])].filter(id=>id!==p.id);save();b.dlg=null;render();btoast('Rekommendationerna har sparats');emit('bs:picked')};

/* ── Alternativ för varianter ── */
PG.options=()=>head(['Alternativ för varianter'],'Alternativ för varianter')+`<div class="bsbody"><h2>Skapa alternativ för varianter</h2><p class="lead" style="max-width:560px">Om du vill ha varianter på dina produkter så behöver du först skapa alternativ. Här kan du skapa och hantera dina alternativ, så som storlek, färg eller material.</p>
 <div class="rowr">${addPill('Skapa alternativ','optform','bs-opt-add')}</div>${D().options.map(o=>`<div class="card" data-g="opt-${slug(o.name)}"><span class="c1"><span style="opacity:.4">⠿</span>${esc(o.name)}</span><span class="c2">${o.at}</span><span class="c3" style="color:#555">${o.values.map(esc).join(', ')}</span><span class="act"><span class="ms">expand_more</span></span></div>`).join('')}${pager(D().options.length)}</div>`;
INIT.optform=()=>{UI.f.b_ovals=['']};
PG.optform=()=>head(['Alternativ för varianter','Skapa alternativ'],'Skapa alternativ')+`<div class="bsbody"><h3 style="margin-top:0">Grunduppgifter</h3><div style="width:284px">${lbl('Namn',1)}${inp('b_oname')}</div><hr><h3 style="margin-top:0">Värden</h3><div class="vlist">${(UI.f.b_ovals||['']).map((v,i)=>`<div>${lbl('Värde',1)}<div class="crow" style="margin:0">${inp('b_oval'+i)}<button data-a="bsovdel" data-x="${i}" class="ms" style="font-size:18px;background:#ddd;border-radius:50%;width:26px;height:26px;display:grid;place-items:center">delete</button></div></div>`).join('')}</div><div style="margin-top:12px">${actPill('Lägg till värde','bsovadd','opt-val-add')}</div></div>`;
SAVES.optform=['bssaveopt'];
A.bsovadd=()=>{(UI.f.b_ovals=UI.f.b_ovals||['']).push('');render();emit('bs:ovadd')};
A.bsovdel=i=>{const L=UI.f.b_ovals;if(L.length>1){for(let k=+i;k<L.length-1;k++)UI.f['b_oval'+k]=UI.f['b_oval'+(k+1)];delete UI.f['b_oval'+(L.length-1)];L.pop()}render()};
A.bssaveopt=()=>{const vals=(UI.f.b_ovals||[]).map((_,i)=>F('b_oval'+i).trim()).filter(Boolean);if(!need(['b_oname']))return;if(!vals.length){B().err.b_oval0=1;render();return}
 const o={id:'o'+Date.now().toString(36),name:F('b_oname').trim(),values:vals,at:today()};D().options.push(o);save();go('options');btoast('Alternativet har skapats');emit('bs:save:opt',o)};

/* ── Ingredienser ── */
PG.ingredients=()=>{const d=D();return head(['Ingredienser'],'Ingredienser')+`<div class="bsbody"><div style="display:flex;align-items:center;gap:10px"><h2 style="font-size:20px;margin:0;padding-right:12px;border-right:1px solid #ddd;font-weight:500">Ingrediensgrupper</h2><button data-a="bsgo" data-x="inggroup" data-g="ing-grp-add" style="display:grid"><span class="ms" style="font-size:22px">add_circle</span></button></div>
 <div class="chips">${d.ingGroups.map(g=>`<span class="chip ${g.color==='#ffffff'?'n':''}" style="background:${g.color}">${esc(g.name)}</span>`).join('')}</div><hr><div class="rowr">${addPill('Lägg till ny ingrediens','ingform','ing-add-new')}</div>${tool('Sök','2/2')}
 <table class="bt"><tr><th>Namn</th><th>Enhet</th><th>Ingrediensgrupp</th><th style="width:50px"></th></tr>${d.ingredients.map(i=>`<tr data-g="ing-${slug(i.name)}"><td>${esc(i.name)}</td><td>${esc(i.unit)}</td><td>${esc((d.ingGroups.find(g=>g.id===i.gid)||{}).name||'')}</td><td><span class="ms" style="font-size:16px">open_in_new</span> <span class="ms" style="font-size:16px">delete</span></td></tr>`).join('')}</table>${pager(d.ingredients.length)}</div>`};
PG.inggroup=()=>head(['Ingredienser','Lägg till ingrediensgrupp'],'Lägg till ingrediensgrupp')+`<div class="bsbody"><div class="grid2"><div>${lbl('Namn',1)}${inp('b_igname')}</div><div>${lbl('Färg',1)}${dd('b_igcolor',SW.map(s=>[s[0],s[0],s[1]]),'Välj färg')}</div></div><hr>${lbl('Butikstillgänglighet',1)}${rad('b_igav','all','Alla butiker','all')}${rad('b_igav','sel','Välj butiker','all')}</div>`;
SAVES.inggroup=['bssaveinggroup'];
A.bssaveinggroup=()=>{if(!need(['b_igname','b_igcolor']))return;const g={id:'ig'+Date.now().toString(36),name:F('b_igname').trim(),color:swOf(F('b_igcolor'))};D().ingGroups.push(g);save();go('ingredients');btoast('Ingrediensgruppen har skapats');emit('bs:save:inggroup',g)};
PG.ingform=()=>head(['Ingredienser','Lägg till ny ingrediens'],'Lägg till ny ingrediens')+`<div class="bsbody"><div style="width:284px">${lbl('Ingrediensgrupp',1)}${dd('b_igid',D().ingGroups.map(g=>[g.id,g.name]),'Sök på ingrediensgrupp')}</div><hr class="d"><div style="width:284px">${lbl('Namn',1)}${inp('b_iname')}</div><div style="width:580px;margin-top:12px">${lbl('Beskrivning')}${ta('b_idesc')}</div>${tr}
 <div style="width:284px">${lbl('Enhet',1)}${dd('b_iunit',[['g','Gram (g)'],['kg','Kilogram (kg)'],['ml','Milliliter (ml)'],['cl','Centiliter (cl)'],['l','Liter (l)'],['st','Styck (st)']],'Välj enhet')}</div><hr>${lbl('Koppla produkten till butikerna där den ska synas',1)}${rad('b_iav','all','Alla butiker','all')}${rad('b_iav','sel','Välj butiker','all')}</div>`;
SAVES.ingform=['bssaveing'];
A.bssaveing=()=>{if(!need(['b_igid','b_iname','b_iunit']))return;const i={id:'i'+Date.now().toString(36),name:F('b_iname').trim(),unit:F('b_iunit'),gid:F('b_igid')};D().ingredients.push(i);save();go('ingredients');btoast('Ingrediensen har skapats');emit('bs:save:ing',i)};

/* ── Tillval (modifier sets) ── */
PG.modifiers=()=>head(['Tillval'],'Tillval')+`<div class="bsbody"><h2>Hantera dina tillvalsgrupper</h2><p class="lead">Tillval används för tillägg eller ändringar av dina produkter, till exempel extra topping eller stekgrad. Tillval skapas i grupper. När gruppen är skapad kopplar du den till produkterna.</p><hr>
 <div class="rowr">${addPill('Skapa ny tillvalsgrupp','modform','bs-mod-add')}</div>
 ${S.modifiers.filter(m=>!m.variant).map(m=>`<div class="card" data-g="mset-${slug(m.name)}"><span class="c1"><span style="opacity:.4">⠿</span>${esc(m.name)}</span><span class="c2" style="width:300px">${m.opts.length} tillval · ${m.pids.length} produkter</span><span class="c3"><span class="bbdg ${m.req?'p':'v'}">${m.req?'OBLIGATORISK':'VALFRI'}</span></span><span class="act">${ibtn('link','bsgo','modset|'+m.id,'mset-open-'+slug(m.name),'Koppla produkter')}</span></div>`).join('')}</div>`;
PG.modform=()=>{const items=UI.f.b_mitems||[];return head(['Tillval','Skapa ny tillvalsgrupp'],'Skapa ny tillvalsgrupp')+`<div class="bsbody"><h3 style="margin-top:0">Allmänna inställningar</h3><div style="width:284px">${lbl('Namn',1)}${inp('b_mname')}</div><div style="margin-top:12px;width:580px">${lbl('Beskrivning')}${ta('b_mdesc')}</div>${tr}
 <h3>Regler för tillval</h3>${chk('b_mreq','Kräver val')}<div style="width:284px;margin-top:6px">${lbl('Max antal tillval från den här gruppen')}${inp('b_mmax',{type:'number'})}<div class="help">Fyll i för att sätta en maxgräns</div></div>${chk('b_mopen','Öppna alltid detaljvyn i kassan vid försäljning')}<hr>
 <div style="display:flex;justify-content:space-between;align-items:flex-start"><div><h3 style="margin-top:0">Tillvalsartiklar</h3><p class="lead">Lägg till, redigera och sortera tillvalen som hör till tillvalsgruppen</p></div>${actPill('Lägg till tillval','bsmodnew','bs-modi-add')}</div>
 ${items.length?`<table class="bt" style="margin-top:10px;max-width:720px"><tr><th>Namn</th><th>Pris inkl. moms</th><th>Förvalt</th></tr>${items.map(o=>`<tr><td>${esc(o.name)}</td><td>${kr(o.price)}</td><td>${o.pre?'Ja':'Nej'}</td></tr>`).join('')}</table>`:`<div style="background:#f1f1f1;padding:10px 12px;font-size:11.5px;margin-top:10px;max-width:720px">Inga tillval har skapats än, lägg till minst en tillvalsartikel</div>`}</div>
 ${B().side==='modi'?BS.sideP('Lägg till tillval',`<h3 style="margin-top:0">Allmänna inställningar</h3>${lbl('Namn',1)}${inp('b_miname')}<hr class="d">${lbl('Pris inkl. moms',1)}${inp('b_miprice',{type:'number',ph:'SEK 0'})}<div class="help">Ange 0 om tillvalet inte ska påverka priset.</div>${chk('b_mipre','Förvalt')}<hr><h3>Allergener och specialkost</h3><button class="addbox"><span class="ms">add</span>Lägg till allergener och specialkost</button><hr><h3>Ingredienser</h3><button class="addbox"><span class="ms">add</span>Lägg till ingredienser</button>`,`<button class="p" data-a="bsmodadd" data-g="bs-modi-create">Skapa och lägg till ny</button><button data-a="bssideclose" data-g="bs-modi-close">Stäng</button>`):''}`};
SAVES.modform=['bssavemod'];
A.bsmodnew=()=>{B().side='modi';UI.f.b_miname='';UI.f.b_miprice='';UI.f.b_mipre=false;render();emit('bs:side')};
A.bsmodadd=()=>{if(!need(['b_miname']))return;(UI.f.b_mitems=UI.f.b_mitems||[]).push({name:F('b_miname').trim(),price:+F('b_miprice')||0,pre:!!UI.f.b_mipre});UI.f.b_miname='';UI.f.b_miprice='';UI.f.b_mipre=false;render();emit('bs:modi')};
A.bssavemod=()=>{if(!need(['b_mname']))return;if(!(UI.f.b_mitems||[]).length){btoast('Lägg till minst ett tillval');return}
 const max=+F('b_mmax')||0;const m={id:'m'+Date.now().toString(36),name:F('b_mname').trim(),multi:max!==1,req:!!UI.f.b_mreq,opts:UI.f.b_mitems.map(o=>({name:o.name,price:o.price})),pids:[]};S.modifiers.push(m);save();go('modset',m.id);btoast('Tillvalsgruppen har skapats');emit('bs:save:mod',m)};
PG.modset=()=>{const m=S.modifiers.find(x=>x.id===B().arg);if(!m)return '';return head(['Tillval',m.name],esc(m.name))+`<div class="bsbody"><table class="bt" style="max-width:720px"><tr><th>Tillval</th><th>Pris inkl. moms</th></tr>${m.opts.map(o=>`<tr><td>${esc(o.name)}</td><td>${kr(o.price)}</td></tr>`).join('')}</table><hr>
 <div style="display:flex;justify-content:space-between;align-items:center;max-width:720px"><h3 style="margin:0">Kopplade produkter (${m.pids.length})</h3>${actPill('Koppla produkter','bspick','mod-link','mod')}</div>${m.pids.length?`<div class="chips">${m.pids.map(id=>`<span class="chip n">${esc((P(id)||{}).name)}</span>`).join('')}</div>`:'<p class="lead" style="margin-top:8px">Inga produkter är kopplade ännu.</p>'}</div>`+pickDlg()};
const _pok2=A.bspickok;A.bspickok=()=>{const b=B();if(b.pickFor!=='mod')return _pok2();const m=S.modifiers.find(x=>x.id===b.arg);m.pids=[...new Set([...m.pids,...b.pick.p,...S.products.filter(x=>b.pick.g.includes(x.gid)).map(x=>x.id)])];save();b.dlg=null;render();btoast('Produkterna har kopplats');emit('bs:picked')};

/* ── Prislistor ── */
PG.pricelists=()=>{const d=D();return head(['Prislistor'],'Prislistor')+`<div class="bsbody"><h2>Hantera dina prislistor</h2><p class="lead" style="max-width:640px">Prislistor tillämpar automatiskt olika priser och, om det har konfigurerats, momssatser i kassan</p><p class="lead" style="max-width:640px"><b>För att komma igång:</b> Skapa en prislista, lägg sedan till produkter och ange deras priser. Prislistan börjar gälla när produkter och priser har lagts till.</p><hr>
 ${d.priceLists.map(l=>{const n=Object.keys(l.prices).length;return `<div class="card" style="height:58px" data-g="pl-${l.id}"><span class="c1" style="width:260px">${esc(l.name)}</span><span class="c2"><span class="bbdg v">FÖRDEFINIERAD</span></span><span class="c3">${n?`<span style="color:#15803d">● Aktiv – ${n} produkter</span>`:'<span style="color:#9a5b00">⚠ Inaktiv - inga kopplade produkter</span>'}</span><span class="act"><button class="pill" style="background:#fff;border:1px solid #111" data-a="bsgo" data-x="plprods|${l.id}" data-g="pl-manage-${l.id}"><span class="ms" style="background:none;color:#111">payments</span>Hantera produkter</button><span class="ms">expand_more</span></span></div>`}).join('')}</div>`};
PG.plprods=()=>{const l=D().priceLists.find(x=>x.id===B().arg);const sel=B().plsel||[];const gf=B().plg;const L=S.products.filter(p=>!gf||p.gid===gf);
 return head(['Prislistor','Hantera produktpriser'],esc(l.name))+`<div class="bsbody"><h2>Hantera produktpriser</h2><p class="lead" style="max-width:560px">För att använda prislistan, lägg till ett extra pris för varje produkt – individuellt eller i bulk. Priset kan vara samma som standardpriset eller skilja sig.</p>
 ${Object.keys(l.prices).length?'':'<div class="warn" style="margin-top:14px"><span class="ms">warning</span>Prislistan är tom: Du har inte lagt till några priser till den här listan ännu</div>'}
 <div class="tool" style="margin-top:14px"><div style="width:200px">${dd('b_plg',[['','Alla grupper'],...S.groups.map(g=>[g.id,g.name])],'Filtrera på grupp',{sm:1})}</div><span style="font-size:11.5px;margin-left:10px">${sel.length}/${S.products.length} valda produkter</span><div class="tb2"><button class="pill" style="padding:5px 10px" data-a="bsplbulk" data-g="pl-bulk">Redigera priser för valda</button><button class="pill" style="padding:5px 10px" data-a="bsplrm">Ta bort pris från prislistan</button></div></div>
 <table class="bt"><tr><th style="width:24px"><button data-a="bsplall" data-g="pl-all"><span class="chk ${sel.length&&L.every(p=>sel.includes(p.id))?'on':''}"></span></button></th><th>Namn</th><th>Produktgrupp</th><th>Standardpris</th><th>${esc(l.name)}</th><th>Skillnad</th><th>Momssats</th><th>Moms prislista</th><th></th></tr>
 ${L.map(p=>{const v=l.prices[p.id];const g=G(p.gid)||{};return `<tr data-g="plrow-${slug(p.name)}"><td><button data-a="bsplsel" data-x="${p.id}"><span class="chk ${sel.includes(p.id)?'on':''}"></span></button></td><td>${esc(p.name)}</td><td>${esc((g.name||'').toUpperCase())}</td><td>${kr(p.price)}</td><td>${v!=null?kr(v):'--'}</td><td>${v!=null?kr(v-p.price):'--'}</td><td>${g.vat||0} %</td><td>${v!=null?l.vat+' %':'--'}</td><td>${ibtn('edit','bsplone',p.id,'pl-edit-'+slug(p.name),'Redigera')}</td></tr>`}).join('')}</table></div>
 ${B().dlg==='plp'?dlg('Redigera pris',`<p class="lead">${B().plFor.length} produkt${B().plFor.length>1?'er':''}</p><div style="margin-top:10px">${rad('b_plmode','price','Nytt pris','price')}${rad('b_plmode','pct','Procentuell ändring','price')}${rad('b_plmode','std','Använd standardpris','price')}</div><div style="margin-top:12px">${(F('b_plmode')||'price')==='price'?lbl('Pris inkl. moms',1)+inp('b_plval',{type:'number',ph:'SEK'}):(F('b_plmode')==='pct'?lbl('Ändring i procent (negativ = sänkning)',1)+inp('b_plval',{type:'number',ph:'%'}):'<p class="lead">Produkterna får samma pris som standardpriset.</p>')}</div>`,`<button data-a="bsdlgx">Avbryt</button><button class="p" data-a="bsplok" data-g="pl-ok">Spara</button>`,{h:360}):''}`};
A.bsplsel=id=>{const b=B();b.plsel=b.plsel||[];const i=b.plsel.indexOf(id);i<0?b.plsel.push(id):b.plsel.splice(i,1);render();emit('bs:plsel')};
A.bsplall=()=>{const b=B();const L=S.products.filter(p=>!b.plg||p.gid===b.plg).map(p=>p.id);b.plsel=(b.plsel||[]).length&&L.every(x=>b.plsel.includes(x))?[]:L;render();emit('bs:plsel')};
OPTHOOK.b_plg=v=>{B().plg=v||null};
A.bsplone=id=>{B().plFor=[id];UI.f.b_plmode='price';UI.f.b_plval='';openDlg('plp','bs:dlg:plp')};
A.bsplbulk=()=>{const s=B().plsel||[];if(!s.length){btoast('Markera minst en produkt');return}B().plFor=[...s];UI.f.b_plmode='price';UI.f.b_plval='';openDlg('plp','bs:dlg:plp')};
A.bsplrm=()=>{const l=D().priceLists.find(x=>x.id===B().arg);(B().plsel||[]).forEach(id=>delete l.prices[id]);save();render()};
A.bsplok=()=>{const m=F('b_plmode')||'price';if(m!=='std'&&!need(['b_plval']))return;const l=D().priceLists.find(x=>x.id===B().arg);B().plFor.forEach(id=>{const p=P(id);l.prices[id]=m==='std'?p.price:m==='pct'?Math.round(p.price*(1+(+F('b_plval'))/100)*100)/100:+F('b_plval')});save();B().dlg=null;B().plsel=[];render();btoast('Priserna har sparats');emit('bs:plsave')};

/* ── Import / export (Magic Menu and the import wizard) ── */
PG.impexp=()=>{const st=B().imp||0;const tab=B().tab||'imp';return head(['Import / export'],'Import / export',`<button class="pill" style="background:#fff;border:1px solid #111"><span class="ms" style="background:none;color:#111">download</span>Ladda ner produktdata</button>`)+`<div class="bsbody"><h2>Hantera din produktdata</h2><p class="lead">Importera och exportera din produktkatalog</p>${BS.tabs('imp',[['imp','Importera'],['hist','Historik']],'imp')}
 ${tab==='hist'?`<table class="bt" style="max-width:720px"><tr><th>Datum</th><th>Fil</th><th>Status</th></tr>${(D().imports||[]).map(i=>`<tr><td>${i.at}</td><td>${esc(i.file)}</td><td><span class="bbdg g">KLAR</span></td></tr>`).join('')||'<tr><td colspan="3"><i>Inga importer ännu</i></td></tr>'}</table>`:
 st===0?`<h3>Hur vill du importera?</h3><div class="grid2" style="grid-template-columns:358px 358px">${rcard('b_imm','magic','Magic Menu (Beta)','Ladda upp dina produkter genom att ta en bild av din meny','magic')}${rcard('b_imm','wiz','Product import wizard (Beta)','Ett steg-för-steg-verktyg för att överföra din befintliga produktkatalog till Yabie','magic')}</div><hr>
  ${(F('b_imm')||'magic')==='magic'?`<h3>Magic Menu (Beta)</h3><p class="lead" style="max-width:700px">Ladda upp bilder av din meny och låt Magic Menu skapa din produktkatalog automatiskt. OBS: Magic Menu använder AI-teknologi och kan ibland göra fel. Dubbelkolla resultaten och justera vid behov.</p>`:`<h3>Product import wizard (Beta)</h3><p class="lead" style="max-width:700px">Exportera produktkatalogen från ditt gamla kassasystem som Excel eller CSV och ladda upp filen här.</p>`}
  <button class="imgbox" style="width:400px;margin-top:10px;border:0" data-a="bsimpfile" data-g="imp-file"><div><span class="ms">${(F('b_imm')||'magic')==='magic'?'add_photo_alternate':'upload_file'}</span><br>${B().impFile?`<b>${esc(B().impFile)}</b>`:'Dra filen hit eller klicka för att välja en fil'}</div></button>`:
 st===1?`<div class="info" style="max-width:720px"><span class="ms">auto_awesome</span>Filen analyseras och kolumnerna matchas mot Yabies produktkatalog …</div>`:
 st===2?`<h3>Granska kolumnmatchningen</h3><p class="lead">Vänster: fälten Yabies produktkatalog behöver. Höger: data som hittades i din fil.</p><table class="bt" style="max-width:720px;margin-top:10px"><tr><th>Yabie-fält</th><th>Kolumn i din fil</th></tr>${[['Namn *','b_imc1',['Artikelnamn','Beskrivning']],['Pris inkl. moms *','b_imc2',['Inköpspris','Utpris']],['Produktgrupp *','b_imc3',['Kategori','Avdelning']],['Momssats','b_imc4',['Moms','-']],['SKU / PLU','b_imc5',['Artikelnr','-']]].map(([t,k,o])=>`<tr><td>${t}</td><td style="width:300px">${dd(k,o,'Välj kolumn',{sm:1})}</td></tr>`).join('')}</table>`:
 st===3?`<h3>Förhandsgranskning</h3><table class="bt" style="max-width:720px;margin-top:10px"><tr><th>Namn</th><th>Pris</th><th>Produktgrupp</th></tr>${IMP.map(r=>`<tr><td>${r[0]}</td><td>${kr(r[1])}</td><td>${r[2]}</td></tr>`).join('')}</table><h3>Hur ska produkterna läggas in?</h3>${rad('b_imadd','add','Lägg till i befintlig katalog','add')}${rad('b_imadd','rep','Ersätt hela katalogen','add')}<div class="note">Är katalogen tom spelar valet ingen roll.</div>`:
 `<div class="info" style="max-width:720px;background:#dcfce7"><span class="ms" style="color:#15803d">check_circle</span>${IMP.length} produkter har importerats. De finns nu i produktkatalogen och i kassan.</div>`}</div>`};
const IMP=[['Chokladmuffin',35,'Bakverk'],['Hallonbulle',38,'Bakverk'],['Lingonlemonad',39,'Kalla drycker']];
A.bsimpfile=()=>{B().impFile=(F('b_imm')||'magic')==='magic'?'meny.jpg':'artiklar_export.xlsx';render();emit('bs:impfile')};
FOOT.impexp=()=>{const st=B().imp||0;if((B().tab||'imp')!=='imp')return '';const lab=['Ladda upp','','Importera','Importera','Klar'][st];if(st===1)return '<div class="bsfoot"></div>';
 return `<div class="bsfoot" style="justify-content:flex-end"><button class="bnext ${B().impFile?'ok':''}" data-a="bsimpnext" data-g="imp-next"><span class="ms" style="font-size:17px">${st===0?'upload':'arrow_forward'}</span>${lab}</button></div>`};
A.bsimpnext=()=>{const b=B();const st=b.imp||0;if(st===0){if(!b.impFile){btoast('Välj en fil först');return}if((F('b_imm')||'magic')==='magic'){btoast('Magic Menu öppnas i kassan. Se guiden Magic Menu i kassaläget.');return}b.imp=1;render();emit('bs:imp:1');setTimeout(()=>{b.imp=2;Object.assign(UI.f,{b_imc1:'Artikelnamn',b_imc2:'Inköpspris',b_imc3:'Kategori',b_imc4:'Moms',b_imc5:'Artikelnr'});render();emit('bs:imp:2')},1400);return}
 if(st===2){if(F('b_imc2')!=='Utpris'){btoast('Kontrollera priskolumnen: försäljningspriset ska användas');emit('bs:imp:badprice');return}b.imp=3;render();emit('bs:imp:3');return}
 if(st===3){const rep=F('b_imadd')==='rep';if(rep){S.products=[]}IMP.forEach(r=>{let g=S.groups.find(x=>x.name===r[2]);if(!g){g={id:'g'+Date.now().toString(36)+r[2].length,name:r[2],vat:12,ledger:'3002',color:'#a9fcd3'};S.groups.push(g)}if(!S.products.find(p=>p.name===r[0]))S.products.push({id:'p'+Date.now().toString(36)+r[0].length,name:r[0],price:r[1],gid:g.id})});
  (D().imports=D().imports||[]).unshift({at:today(),file:b.impFile});save();b.imp=4;render();btoast('Importen är klar');emit('bs:imp:done');return}
 b.imp=0;b.impFile=null;render()};
INIT.impexp=()=>{const b=B();b.imp=0;b.impFile=null};

/* ── Popup-meddelanden ── */
PG.popup=()=>head(['Popup-meddelanden'],'Popup-meddelanden')+`<div class="bsbody"><h2>Skapa popup-meddelanden till kassan</h2><p class="lead" style="max-width:640px">Meddelanden kan användas för att informera kassapersonalen om att till exempel be om legitimation vid köp av alkohol. Ett meddelande kan antingen visas första gången en produkt läggs i varukorgen eller varje gång. Du kopplar ett meddelande till en produkt när du skapar eller redigerar produkten.</p>
 <div class="rowr">${addPill('Lägg till popup-meddelande','popform','pop-add')}</div><table class="bt"><tr><th>Namn</th><th>Visa popup</th><th style="width:50px"></th></tr>${D().popups.map(p=>`<tr data-g="pop-${slug(p.name)}"><td>${esc(p.name)}</td><td><span class="bbdg v">${p.once?'EN GÅNG PER ORDER':'FÖR VARJE PRODUKT'}</span></td><td><span class="ms" style="font-size:16px">open_in_new</span> <span class="ms" style="font-size:16px">delete</span></td></tr>`).join('')}</table></div>`;
PG.popform=()=>head(['Popup-meddelanden','Lägg till popup-meddelande'],'Lägg till popup-meddelande')+`<div class="bsbody"><h3 style="margin-top:0">Popup-meddelande</h3><p class="lead">Det är bara texten som visas i kassan</p><div style="width:284px;margin-top:10px">${lbl('Namn',1)}${inp('b_ponm')}<div class="help">Namnet används för att kunna se och välja meddelandet från en lista</div></div><div style="width:580px;margin-top:12px">${lbl('Text',1)}${ta('b_potx')}</div>${tr}
 <h3>Inställningar</h3><p class="lead">Välj om du vill att popup-meddelandet ska visas en gång per order, eller för varje produkt som läggs till i varukorgen</p>${chk('b_poonce','Visa en gång per order')}</div>`;
SAVES.popform=['bssavepop'];
A.bssavepop=()=>{if(!need(['b_ponm','b_potx']))return;const p={id:'pn'+Date.now().toString(36),name:F('b_ponm').trim(),text:F('b_potx').trim(),once:!!UI.f.b_poonce};D().popups.push(p);save();go('popup');btoast('Popup-meddelandet har skapats');emit('bs:save:popup',p)};

/* ── Produktkatalog → Inställningar ── */
PG.psettings=()=>head(['Inställningar'],'Inställningar')+`<div class="bsbody"><h2>Språkinställningar</h2><p class="lead" style="max-width:600px">Välj vilket språk du vill ha som standard för dina produkter, samt om du vill att kassan ska kunna visa produkter på olika språk.</p><h3>Välj språk</h3><div class="crow" style="flex-wrap:wrap;gap:4px 18px;max-width:700px">${['Svenska','Norwegian','English','Dansk','Español','Suomi','Italiano','Nederlands','Português','Français','Deutsch'].map((l,i)=>chk('b_lang_'+i,l,i===0)).join('')}</div><div style="width:284px;margin-top:14px">${lbl('Standardspråk')}${dd('b_deflang',['Svenska','English'],'Svenska')}</div></div>`;
FOOT.psettings=()=>`<div class="bsfoot" style="justify-content:flex-end"><button class="bsave" data-a="bssaved" data-g="bs-save"><span><span class="ms">save</span>Spara</span></button></div>`;
A.bssaved=()=>{btoast('Inställningarna har sparats');emit('bs:saved')};
})();
